//! Per-host token resolution for the platform layer (Gitea / GitLab).
//! (Generated by v0.6.0 Step 3 Phase 1)
//!
//! Divider of responsibilities: GitHub tokens are resolved exclusively by
//! [`crate::github::auth`] (`GITHUB_TOKEN` → `gh auth token`); this module
//! must not duplicate that logic, so [`PlatformKind::GitHub`] is rejected here.
//! Self-hosted remotes never reach a token lookup either —
//! [`crate::platform::build_client`] rejects them first. What remains is
//! [`PlatformKind::GitLab`] (gitlab.com, `GITLAB_TOKEN` → `glab auth token`)
//! and [`PlatformKind::Gitea`] (gitea.com, env-only `GITEA_TOKEN`; Gitea has no
//! standard token CLI). Results are cached per host.

use std::collections::HashMap;
use std::sync::{Mutex, MutexGuard, OnceLock};

use secrecy::SecretString;

use super::error::PlatformError;
use super::remote::PlatformKind;

/// Cached tokens, keyed by host.
type TokenMap = HashMap<String, SecretString>;

/// Per-host token cache, lazily initialized once per process.
static TOKENS: OnceLock<Mutex<TokenMap>> = OnceLock::new();

fn token_store() -> &'static Mutex<TokenMap> {
    TOKENS.get_or_init(|| Mutex::new(HashMap::new()))
}

/// Lock a token map, recovering from a poisoned mutex.
///
/// A panic in an unrelated thread must not turn every later refresh into a
/// `Token` failure, so the (still consistent) inner map is reused.
fn lock_or_recover(map: &Mutex<TokenMap>) -> MutexGuard<'_, TokenMap> {
    map.lock().unwrap_or_else(|e| e.into_inner())
}

/// Lock the process-wide token cache.
fn lock_tokens() -> MutexGuard<'static, TokenMap> {
    lock_or_recover(token_store())
}

/// Resolve a token for `host`/`kind`, caching the result per host.
///
/// Cache lookup, resolution and insertion all happen under a single lock, so
/// concurrent refreshes resolve the token once instead of racing.
pub fn resolve_token(host: &str, kind: PlatformKind) -> Result<SecretString, PlatformError> {
    let mut tokens = lock_tokens();
    if let Some(t) = tokens.get(host) {
        return Ok(t.clone());
    }
    let raw = pick_token(kind, env_token(kind), cli_token(kind))?;
    let secret = SecretString::new(raw.into_boxed_str());
    Ok(tokens
        .entry(host.to_string())
        .or_insert_with(|| secret.clone())
        .clone())
}

/// Pure precedence: a kind this module does not own is rejected; otherwise the
/// env token wins, an empty env falls back to the CLI, and both absent/empty
/// yields a guided [`PlatformError::Token`]. Injectable for unit tests.
pub(crate) fn pick_token(
    kind: PlatformKind,
    env: Option<String>,
    cli: Result<String, String>,
) -> Result<String, PlatformError> {
    let Some((label, env_var)) = env_info(kind) else {
        return Err(PlatformError::Token(format!(
            "{} 的 token 不由本模块解析（GitHub 见 crate::github::auth；自托管暂不支持）",
            kind.as_str()
        )));
    };
    if let Some(t) = env {
        if !t.is_empty() {
            return Ok(t);
        }
    }
    let cli_name = cli_name(kind);
    match cli {
        Ok(t) if !t.is_empty() => Ok(t),
        Ok(_) => Err(PlatformError::Token(format!(
            "{cli_name} auth token 为空，请设置 {env_var} 环境变量"
        ))),
        Err(_) => Err(PlatformError::Token(format!(
            "{cli_name} 不可用，无法自动获取 {label} token；设置 {env_var} 环境变量后重试"
        ))),
    }
}

/// Resolve the env-var name + label used in user-facing messages.
///
/// `None` marks a kind this module does not own: GitHub is resolved by
/// [`crate::github::auth`], self-hosted is rejected by
/// [`crate::platform::build_client`].
fn env_info(kind: PlatformKind) -> Option<(String, String)> {
    match kind {
        PlatformKind::GitLab => Some((PlatformKind::GitLab.as_str().into(), "GITLAB_TOKEN".into())),
        PlatformKind::Gitea => Some((PlatformKind::Gitea.as_str().into(), "GITEA_TOKEN".into())),
        PlatformKind::GitHub | PlatformKind::SelfHosted => None,
    }
}

/// CLI binary name (or sentinel) for user-facing messages.
fn cli_name(kind: PlatformKind) -> &'static str {
    match kind {
        PlatformKind::GitLab => "glab",
        // Gitea has no standard CLI for token resolution.
        PlatformKind::Gitea => "CLI",
        PlatformKind::GitHub | PlatformKind::SelfHosted => "CLI",
    }
}

/// Read the env-var token for `kind`.
///
/// Only the platform's own family var is consulted (`GITLAB_TOKEN` /
/// `GITEA_TOKEN`). Kinds this module does not own yield `None`; [`pick_token`]
/// turns that into a guided error.
fn env_token(kind: PlatformKind) -> Option<String> {
    let name = match kind {
        PlatformKind::GitLab => "GITLAB_TOKEN",
        PlatformKind::Gitea => "GITEA_TOKEN",
        PlatformKind::GitHub | PlatformKind::SelfHosted => return None,
    };
    match std::env::var(name) {
        Ok(t) if !t.is_empty() => Some(t),
        _ => None,
    }
}

/// Run the platform CLI to fetch a token (`glab` for GitLab; Gitea is env-only).
fn cli_token(kind: PlatformKind) -> Result<String, String> {
    match kind {
        PlatformKind::GitLab => cli_glab_token(),
        PlatformKind::Gitea => Err("CLI 不可用".into()),
        PlatformKind::GitHub | PlatformKind::SelfHosted => Err("CLI 不可用".into()),
    }
}

fn cli_glab_token() -> Result<String, String> {
    let out = std::process::Command::new("glab")
        .args(["auth", "token"])
        .output()
        .map_err(|e| format!("glab 不可用：{e}"))?;
    if !out.status.success() {
        return Err(format!(
            "glab auth token 失败（未登录？）：{}",
            String::from_utf8_lossy(&out.stderr).trim()
        ));
    }
    let t = String::from_utf8(out.stdout).map_err(|e| format!("输出非 UTF-8：{e}"))?;
    Ok(t.trim().to_string())
}

#[cfg(test)]
mod tests {
    use super::*;
    use secrecy::ExposeSecret;
    use std::sync::Arc;

    #[test]
    fn cli_name_per_kind() {
        assert_eq!(cli_name(PlatformKind::GitLab), "glab");
        assert_eq!(cli_name(PlatformKind::Gitea), "CLI");
    }

    #[test]
    fn env_info_saas_vars() {
        assert_eq!(
            env_info(PlatformKind::GitLab),
            Some(("GitLab".into(), "GITLAB_TOKEN".into()))
        );
        assert_eq!(
            env_info(PlatformKind::Gitea),
            Some(("Gitea".into(), "GITEA_TOKEN".into()))
        );
        // Owned by crate::github::auth / rejected in build_client.
        assert_eq!(env_info(PlatformKind::GitHub), None);
        assert_eq!(env_info(PlatformKind::SelfHosted), None);
    }

    #[test]
    fn env_token_ignores_kinds_it_does_not_own() {
        assert_eq!(env_token(PlatformKind::GitHub), None);
        assert_eq!(env_token(PlatformKind::SelfHosted), None);
    }

    #[test]
    fn cli_token_is_unavailable_for_kinds_without_cli() {
        assert!(cli_token(PlatformKind::Gitea).is_err());
        assert!(cli_token(PlatformKind::GitHub).is_err());
        assert!(cli_token(PlatformKind::SelfHosted).is_err());
    }

    #[test]
    fn pick_token_rejects_github_and_self_hosted() {
        for kind in [PlatformKind::GitHub, PlatformKind::SelfHosted] {
            let err = pick_token(kind, Some("tok".into()), Ok("cli".into())).unwrap_err();
            match err {
                PlatformError::Token(m) => {
                    assert!(m.contains("不由本模块解析"), "unexpected: {m}")
                }
                other => panic!("expected Token error, got {other:?}"),
            }
        }
    }

    #[test]
    fn pick_token_env_wins() {
        let t = pick_token(
            PlatformKind::GitLab,
            Some("glpat_env".into()),
            Ok("glpat_cli".into()),
        )
        .expect("env wins");
        assert_eq!(t, "glpat_env");
    }

    #[test]
    fn pick_token_cli_fallback_when_env_empty() {
        let t = pick_token(
            PlatformKind::GitLab,
            Some(String::new()),
            Ok("glpat_cli".into()),
        )
        .expect("empty env falls back to cli");
        assert_eq!(t, "glpat_cli");
    }

    #[test]
    fn pick_token_empty_cli_is_error() {
        let err = pick_token(PlatformKind::GitLab, None, Ok(String::new())).unwrap_err();
        assert!(matches!(err, PlatformError::Token(_)));
        assert!(err.to_string().contains("GITLAB_TOKEN"));
    }

    #[test]
    fn pick_token_no_env_no_cli_is_error() {
        let err = pick_token(PlatformKind::Gitea, None, Err("CLI 不可用".into())).unwrap_err();
        assert!(matches!(err, PlatformError::Token(_)));
        assert!(err.to_string().contains("GITEA_TOKEN"));
    }

    #[test]
    fn lock_or_recover_survives_a_poisoned_mutex() {
        let map = Arc::new(Mutex::new(TokenMap::new()));
        let panicking = Arc::clone(&map);
        let _ = std::thread::spawn(move || {
            let _guard = panicking.lock().expect("first lock is clean");
            panic!("poison on purpose");
        })
        .join();
        assert!(map.is_poisoned(), "guard thread panicked");

        lock_or_recover(&map).insert(
            "host".to_string(),
            SecretString::new("tok".to_string().into_boxed_str()),
        );
        let got = lock_or_recover(&map)
            .get("host")
            .map(|s| s.expose_secret().to_string());
        assert_eq!(got.as_deref(), Some("tok"));
    }

    #[test]
    fn resolve_token_is_concurrency_safe() {
        // A dedicated host keeps this test independent from the real ones.
        if std::env::var("GITEA_TOKEN").is_err() {
            std::env::set_var("GITEA_TOKEN", "gitea-test-token");
        }
        let host = "concurrency-test.example";
        let handles: Vec<_> = (0..8)
            .map(|_| {
                let host = host.to_string();
                std::thread::spawn(move || resolve_token(&host, PlatformKind::Gitea))
            })
            .collect();
        let mut tokens = Vec::new();
        for h in handles {
            // Threads must never panic (poisoned lock included).
            tokens.push(
                h.join()
                    .expect("no panic")
                    .expect("gitea token resolves from env")
                    .expose_secret()
                    .to_string(),
            );
        }
        assert!(!tokens.is_empty());
        assert!(tokens.iter().all(|t| t == &tokens[0]));
    }

    #[test]
    fn resolve_token_caches_per_host() {
        if std::env::var("GITEA_TOKEN").is_err() {
            std::env::set_var("GITEA_TOKEN", "gitea-test-token");
        }
        let host = "cache-test.example";
        let first = resolve_token(host, PlatformKind::Gitea).expect("first resolve");
        let second = resolve_token(host, PlatformKind::Gitea).expect("cached resolve");
        assert_eq!(
            first.expose_secret().to_string(),
            second.expose_secret().to_string()
        );
    }

    #[test]
    fn resolve_token_rejects_github() {
        let err = resolve_token("github-token-reject.example", PlatformKind::GitHub)
            .expect_err("github is not this module's job");
        assert!(matches!(err, PlatformError::Token(_)));
        assert!(err.to_string().contains("不由本模块解析"));
    }
}
